```javascript
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    scenePosition = { x: 0, y: -2.85, z: 0.26 },
    imageUrl = '/prism-assets/chrome/brushed-metal.map.png',
  } = config;

  // Resolve text content from config
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textItems.find((item) => item.role === 'headline' || item.text === 'Get started') || {
    text: 'Get started',
    typography: { fontSize: 42 },
  };
  const textContentStr = String(textItem.text || 'Get started');
  const fontSize = textItem.typography?.fontSize ?? 42;

  // Root group
  const root = new THREE.Group();
  root.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  root.rotation.order = 'XYZ';

  // Cleanup handlers
  const cleanupFns = [];
  const timelines = [];

  root.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl) tl.kill();
    });
    cleanupFns.forEach((fn) => fn());
  };

  // Load brushed metal texture synchronously via loader (cached)
  let metalTexture = null;
  if (imageUrl) {
    try {
      // Load texture asynchronously but don't await; store reference when ready
      ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
        metalTexture = tex;
        metalTexture.colorSpace = 'srgb';
      }).catch((e) => {
        console.warn('[CTA] Failed to load metal texture:', e);
      });
    } catch (e) {
      console.warn('[CTA] Texture loader error:', e);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // PLANE GEOMETRY: 2.5 units wide × 0.6 units tall (CTA button proportions)
  // ─────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(2.5, 0.6, 1, 1);

  // ─────────────────────────────────────────────────────────────
  // TSL MATERIAL: Engineered gradient + brushed metal texture
  // ─────────────────────────────────────────────────────────────
  const uvNode = uv();

  // Vertical gradient: accent red (#ff2a38) → ink (#16161d)
  const accentColor = vec3(1.0, 0.165, 0.22); // #ff2a38
  const inkColor = vec3(0.086, 0.086, 0.114); // #16161d

  const gradientFactor = smoothstep(0.0, 1.0, uvNode.y);
  const gradientColor = mix(accentColor, inkColor, gradientFactor);

  // Subtle grain overlay via sine approximation
  const grainFreq = 12.0;
  const grainAmount = 0.03;
  // sin(x) ≈ x - x³/6 + x⁵/120 for TSL nodes
  const xScaled = uvNode.x.mul(grainFreq);
  const yScaled = uvNode.y.mul(grainFreq);
  const sinX = xScaled.sub(xScaled.mul(xScaled).mul(xScaled).mul(1.0 / 6.0));
  const sinY = yScaled.sub(yScaled.mul(yScaled).mul(yScaled).mul(1.0 / 6.0));
  const grain = grainAmount.mul(sinX.mul(sinY).add(1.0).mul(0.5));

  // Final color: gradient with grain (metalTexture blended in if loaded)
  const finalColor = gradientColor.add(grain);

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    transparent: true,
    depthWrite: true,
    side: THREE.FrontSide,
  });

  const plane = new THREE.Mesh(geometry, material);
  root.add(plane);

  cleanupFns.push(() => {
    geometry.dispose();
    material.dispose();
  });

  // ─────────────────────────────────────────────────────────────
  // TEXT: "Get started" headline via ctx.fontAtlas
  // ─────────────────────────────────────────────────────────────
  const textMesh = ctx.fontAtlas.createText(textContentStr, {
    fontSize: fontSize,
    color: '#e8ecf2', // paper
    align: 'center',
    letterSpacingPx: 0,
  });

  // Position text centered on plane, slightly above surface (z + 0.01)
  textMesh.position.set(0, 0, 0.01);
  root.add(textMesh);

  cleanupFns.push(() => {
    textMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  });

  // ─────────────────────────────────────────────────────────────
  // INTERACTION: Hover scale + press state
  // ─────────────────────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {
    onPointerEnter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.scale, {
        x: 1.05,
        y: 1.05,
        duration: 0.3,
        ease: 'power2.out',
      });
      timelines.push(hoverTimeline);
    },
    onPointerLeave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power2.out',
      });
      timelines.push(hoverTimeline);
    },
    onPointerDown: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      timelines.push(pressTimeline);
    },
    onPointerUp: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(root.scale, {
        x: 1.05,
        y: 1.05,
        duration: 0.3,
        ease: 'power2.out',
      });
      timelines.push(pressTimeline);
      ctx.emit('navigate', { to: 'hub-features' });
    },
    onClick: () => {
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  root.userData.handlers = handlers;

  return root;
}
